const topicNames = {
  T: 'Amir Temur davlati',
  M: 'Temuriylar davri',
  R: "Uyg'onish davri",
  G: 'Buyuk geografik kashfiyotlar',
  N: 'Yangi davr',
  C: 'Jahon xronologiyasi',
  K: 'Xonliklar davri',
  B: 'Rossiya bosqini',
  S: 'Sanoat inqilobi'
}

const makeQuestions = (items, grade, section, firstId) => items.map(
  ([topic, savol, answer, wrong1, wrong2, izoh], index) => {
    const togriJavob = index % 3
    const variantlar = [wrong1, wrong2]
    variantlar.splice(togriJavob, 0, answer)

    return {
      id: firstId + index,
      sinf: grade,
      bolim: section,
      mavzu: topicNames[topic],
      qiyinlik: ['oson', 'orta', 'qiyin'][index % 3],
      savol,
      variantlar: variantlar.map((variant, optionIndex) => `${String.fromCharCode(65 + optionIndex)}) ${variant}`),
      togriJavob,
      izoh
    }
  }
)

